CREATE INDEX inventory_location_balance_inventory_item_variant_id_ix ON inventory.inventory_location_balance (tenant_id, inventory_item_variant_id);
ALTER TABLE inventory.inventory_location_balance ADD CONSTRAINT inventory_location_balance_location_id_fk FOREIGN KEY (tenant_id, property_id, location_id) REFERENCES resources.location (tenant_id, property_id, location_id) ON DELETE RESTRICT;
CREATE INDEX inventory_location_balance_location_id_ix ON inventory.inventory_location_balance (tenant_id, property_id, location_id);
ALTER TABLE inventory.inventory_location_balance ADD CONSTRAINT inventory_location_balance_product_lot_id_fk FOREIGN KEY (tenant_id, product_lot_id) REFERENCES inventory.product_lot (tenant_id, product_lot_id) ON DELETE RESTRICT;
CREATE INDEX inventory_location_balance_product_lot_id_ix ON inventory.inventory_location_balance (tenant_id, product_lot_id);
ALTER TABLE inventory.inventory_location_balance ADD CONSTRAINT inventory_location_balance_tenant_fk FOREIGN KEY (tenant_id) REFERENCES core.tenant (tenant_id);
ALTER TABLE inventory.inventory_location_balance ADD CONSTRAINT inventory_location_balance_property_fk FOREIGN KEY (tenant_id, property_id) REFERENCES core.property (tenant_id, property_id);
ALTER TABLE inventory.inventory_ledger_entry ADD CONSTRAINT inventory_ledger_entry_inventory_item_variant_id_fk FOREIGN KEY (tenant_id, inventory_item_variant_id) REFERENCES inventory.inventory_item_variant (tenant_id, inventory_item_variant_id) ON DELETE RESTRICT;
CREATE INDEX inventory_ledger_entry_inventory_item_variant_id_ix ON inventory.inventory_ledger_entry (tenant_id, inventory_item_variant_id);
ALTER TABLE inventory.inventory_ledger_entry ADD CONSTRAINT inventory_ledger_entry_location_id_fk FOREIGN KEY (tenant_id, property_id, location_id) REFERENCES resources.location (tenant_id, property_id, location_id) ON DELETE RESTRICT;
CREATE INDEX inventory_ledger_entry_location_id_ix ON inventory.inventory_ledger_entry (tenant_id, property_id, location_id);
