CREATE TRIGGER stock_count_touch BEFORE UPDATE ON inventory.stock_count FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER service_product_use_append_only BEFORE UPDATE OR DELETE ON inventory.service_product_use FOR EACH ROW EXECUTE FUNCTION core.forbid_mutation();
